const NORMAL_PREFIX='unruly-workspace-u1-normal-';
const CACHE=NORMAL_PREFIX+'v10-20261025-motiondock-1';
const FILES=['./','./index.html','./style.css','./pose.css','./pose-model.js','./pose-hair.js','./pose-ui.js','./drawing-reference.js','./drawing-reference-ui.js','./pose-detection.js','./raster.js','./raster-tiles.js','./smudge.js','./pixel-paint.js','./image-tip-paint.js','./pixel-surface.js','./smudge-ui.js','./connectors.js','./selection.js','./brushes.js','./brush-recipe.js','./brush-recipe-ui.js','./brush-size.js','./u2.js','./palettes.js','./palettes-ui.js','./pen-input.js','./pressure-ui.js','./brush-compare.js','./gestures.js','./shapes.js','./folders.js','./masks.js','./clipping.js','./text.js','./rich-text-layout.js','./image-import.js','./pattern-warp.js','./pattern-warp-ui.js','./pattern-mesh.js','./pattern-mesh-ui.js','./wand.js','./lasso-region.js','./path-selection.js','./path-selection-ui.js','./magnetic-selection.js','./bucket-fill.js','./polygon-fill.js','./image-clipboard.js','./grain.js','./grain-ui.js','./custom-tips.js','./custom-tips-ui.js','./filters.js','./filter-ui.js','./adjustments.js','./adjustment-ui.js','./effect-compositor.js','./group-cache.js','./timelapse.js','./timelapse-store.js','./timelapse-ui.js','./timelapse-video.js','./video-container.js','./motion.js','./motion-region.js','./motion-ui.js','./group-composition.js','./model.js','./history-patch.js','./raster-cache.js','./layer-compositor.js','./render.js','./canvas2d-renderer.js','./render-contract.js','./storage.js','./virtual-groups.js','./virtual-group-session.js','./virtual-group-scene.js','./virtual-project-store.js','./virtual-project-ui.js','./app.js','./artwork-export.js','./export-formats.js','./artwork-export-ui.js','./guides.js','./raster-guides.js','./artwork-geometry.js','./drawing-tools-ui.js','./stabilization.js','./stabilization-ui.js','./manifest.webmanifest','./icon.svg'];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES.map(path=>new Request(path,{cache:'reload'}))))));
self.addEventListener('message',e=>{if(e.data?.type==='ACTIVATE_UPDATE')self.skipWaiting();});
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith(NORMAL_PREFIX)&&k!==CACHE).map(k=>caches.delete(k))))));
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(caches.open(CACHE).then(async c=>(await c.match(e.request))||fetch(e.request)));});

